public final class Contract {                                    // continuity
    public record Version(LocalDate effective, BigDecimal fee, String terms) {}
    private final NavigableMap<LocalDate, Version> history = new TreeMap<>();
    public Version current() { return history.lastEntry().getValue(); }
    public Optional<Version> asOf(LocalDate on) {
        Map.Entry<LocalDate, Version> e = history.floorEntry(on);    // null = Missing Version
        return Optional.ofNullable(e == null ? null : e.getValue());
    }
    public void amend(LocalDate effective, Version working) { history.put(effective, working); }
}

